/bin/bash -lc "set -e
node --version
node --test review/base/test/catalog.test.mjs review/head/test/catalog.test.mjs
node --input-type=module <<'NODE'
import { copyFileSync, mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { isDeepStrictEqual } from 'node:util';

const scratch = mkdtempSync(join(process.cwd(), '.review-check-'));
try {
  for (const version of ['base', 'head']) {
    const { loadCatalog, pinnedTitles, saveCatalog, setPinned } =
      await import("'`./review/${version}/src/catalog.mjs`);
    for (const [id, pinned] of [['"'a', true], ['b', false]]) {
      const path = join(scratch, "'`${version}-${id}.json`);
      copyFileSync(`review/${version}/fixture/catalog.json`, path);
      const expected = setPinned(loadCatalog(path), id, pinned);
      saveCatalog(path, expected);
      const actual = loadCatalog(path);
      console.log(JSON.stringify({
        version, id, pinned, matches: isDeepStrictEqual(actual, expected),
        expectedPinned: pinnedTitles(expected), actualPinned: pinnedTitles(actual),
      }));
    }
  }
} finally {
  rmSync(scratch, { recursive: true });
}
NODE
